/*
 * MST_$UNMAP_PRIVI - Unmap a range of segments of an address space
 *
 * Original address: 0x00E448B0 (SAU2 map: MST_$UNMAP_PRIVI at E448B0)
 * Size: 510 bytes (0x00E448B0 .. 0x00E44AAD)
 * Generated by: Claude Opus 5.5 (reviewed by Claude Fable 5.1)
 *
 * Frame (link.w A6,-0xA8; D2-D6/A2-A3/A5 saved; A5 = 0xE7CF0C, MST_UNWIRED,
 * never used):
 *   (0x08,A6) mode    word (D3w), a bit set:
 *                       bit 0  the range may lie below MST_$SEG_PRIVATE_B
 *                       bit 1  every segment must be mapped to *uid
 *                              (else status_$mst_object_is_not_mapped)
 *                       bit 2  keep the MSTE, marking it (bit 14 of its
 *                              +0x0A word) instead of clearing its UID
 *                       bit 4  only VM areas (ANON UIDs) may be unmapped
 *   (0x0A,A6) uid     -> the object UID (copied to A6-0x88)
 *   (0x0E,A6) start   VA; rounded down to a 32 KB segment (D6)
 *   (0x12,A6) size    bytes
 *   (0x16,A6) asid    word
 *   (0x18,A6) status  (A3)
 *   (-0x8C) result, (-0x9A) last_seg, (-0x9C) first_seg
 *   D2w the segment within the ASID's table, D4w its MST_$VA_TO_SEGNO
 *   segment number, D5w MST_ASID_BASE[D4w].
 *
 * Blocks:
 *   0x00E448CA-0x00E448F8  copy the UID; round start; the private-B check
 *   0x00E448FA-0x00E4494A  range checks: end must be above start, both ends
 *                          must translate to the same segment number <= 0x39
 *   0x00E44956-0x00E44976  lock 0xC, result = 0
 *   0x00E4497A-0x00E44A90  per segment: find its MSTE (1-based page-table
 *                          page); skip an empty one; an ANON UID is a VM
 *                          area segment (AREA_$REMOVE_SEG), anything else
 *                          an object segment (MST_$REMOVE_SEG); then clear
 *                          the MSTE's +0x0A word below bit 9 and either mark
 *                          it or clear its UID
 *   0x00E44A60-0x00E44A8A  no page-table page: skip to the next 64-segment
 *                          block (or fail under mode bit 1)
 *   0x00E44A94-0x00E44AA0  unlock; *status = result
 *
 * Quirks reproduced:
 *   - Skipping a missing page-table page advances start by 64 segments'
 *     worth (0x200000) whatever the position in the block: the step is
 *     computed from D2w after it was rounded up (0x00E44A7A).
 *   - The range errors return before the lock is taken; a per-segment error
 *     stops the walk with the lock released.
 *   - A5 is loaded but never used.
 */

#include "mst/mst_internal.h"
#include "anon/anon.h"
#include "area/area.h"

/* Mode bits (D3w) */
#define MST_UNMAP_ANY_SEG       0x0001  /* btst #0 0x00E448E2 */
#define MST_UNMAP_MATCH_UID     0x0002  /* btst #1 0x00E449AE */
#define MST_UNMAP_KEEP_ENTRY    0x0004  /* btst #2 0x00E44A44 */
#define MST_UNMAP_AREAS_ONLY    0x0010  /* btst #4 0x00E449DE */

/* ML lock of the MST: `move.w #0xc,-(SP)` 0x00E44958 */
#define MST_UNMAP_LOCK          0x0C

/* Highest MST_$VA_TO_SEGNO segment number: `cmpi.w #0x39` 0x00E44942 */
#define MST_UNMAP_MAX_SEGNO     0x39

/* Segments per page-table page and the segment shift */
#define MST_UNMAP_SEGS_PER_PAGE 0x40
#define MST_UNMAP_SEG_SHIFT     15

/* The MSTE's +0x0A word: bits kept (andi.w #-0x200) and the mark (bset #6) */
#define MSTE_0A_KEEP_MASK       0xFE00
#define MSTE_0A_UNMAPPED        0x4000

/* An object segment whose location byte field (+0x0C bits 6..2) is 0x1F */
#define MSTE_LOC_FIELD_MASK     0x7C
#define MSTE_LOC_FIELD_ALL      0x1F

void MST_$UNMAP_PRIVI(int16_t mode, uid_t *uid, uint32_t start, uint32_t size,
                      uint16_t asid, status_$t *status)
{
    uid_t want;                         /* (-0x88,A6) */
    status_$t result;                   /* (-0x8C,A6) */
    uint16_t last_seg;                  /* (-0x9A,A6) */
    uint16_t first_seg;                 /* (-0x9C,A6) */
    uint32_t va;                        /* D6 */
    uint32_t end;                       /* D5 */
    uint16_t seg;                       /* D2w */
    uint16_t segno;                     /* D4w */
    uint16_t end_segno;                 /* D0w at 0x00E44948 */
    uint16_t base;                      /* D5w */
    uint16_t page;
    int16_t mst_index;
    mste_t *mste;                       /* A2 - 0x400 */
    int8_t anon;

    /* 0x00E448CA-0x00E448F8 */
    want = *uid;
    va = start & 0xFFFF8000u;
    if ((mode & MST_UNMAP_ANY_SEG) == 0 &&
        (va >> MST_UNMAP_SEG_SHIFT) >= (uint32_t)MST_$SEG_PRIVATE_B) {
        *status = status_$reference_to_illegal_address;   /* 0x00E4494C */
        return;
    }

    /* 0x00E448FA-0x00E4494A */
    end = start + size;
    if (!(end > start)) {
        *status = status_$mst_invalid_length;
        return;
    }
    segno = MST_$VA_TO_SEGNO(va, &first_seg, asid);
    seg = first_seg;
    /* Both translations run before either test (0x00E44924-0x00E4494A). */
    end_segno = MST_$VA_TO_SEGNO(end - 1, &last_seg, asid);
    if (segno > MST_UNMAP_MAX_SEGNO || segno != end_segno) {
        *status = status_$reference_to_illegal_address;
        return;
    }

    /* 0x00E44956-0x00E44976 */
    ML_$LOCK(MST_UNMAP_LOCK);
    result = status_$ok;
    base = MST_ASID_BASE[segno];

    while (seg <= last_seg) {
        /* 0x00E4497A-0x00E449AA */
        mst_index = (int16_t)((int16_t)(seg >> 6) + (int16_t)base);
        page = MST[mst_index];
        if (page == 0) {
            /* 0x00E44A60-0x00E44A8A */
            if ((mode & MST_UNMAP_MATCH_UID) != 0) {
                result = status_$mst_object_is_not_mapped;
                break;
            }
            seg = (uint16_t)(seg + (MST_UNMAP_SEGS_PER_PAGE - (seg & 0x3F)));
            va += (uint32_t)(MST_UNMAP_SEGS_PER_PAGE - (uint32_t)(seg & 0x3F))
                  << MST_UNMAP_SEG_SHIFT;
            continue;
        }
        mste = (mste_t *)ARCH_VA_TO_PTR(MST_PAGE_TABLE_BASE +
                                        (uint32_t)page * 0x400u +
                                        (uint32_t)((seg & 0x3F) << 4) - 0x400u);

        /* 0x00E449AE-0x00E449CE */
        if ((mode & MST_UNMAP_MATCH_UID) != 0 &&
            (mste->uid.high != want.high || mste->uid.low != want.low)) {
            result = status_$mst_object_is_not_mapped;    /* 0x00E44A66 */
            break;
        }
        if (mste->uid.high == 0) {
            goto next;                                    /* 0x00E44A56 */
        }

        /* 0x00E449D2-0x00E449F6 */
        anon = (mste->uid.high == ANON_$UID.high) ? (int8_t)0xFF : 0;
        if ((mode & MST_UNMAP_AREAS_ONLY) != 0 && anon >= 0) {
            result = status_$mst_uid_not_vm_area;
            break;
        }

        if (anon < 0) {
            /* 0x00E449F8-0x00E44A16: a VM area segment */
            AREA_$REMOVE_SEG(&mste->uid.low, segno, seg,
                             ((mode & MST_UNMAP_KEEP_ENTRY) == 0) ? (int8_t)0xFF : 0,
                             mste->segment, &result);
        } else {
            /* 0x00E44A18-0x00E44A38: an object segment */
            MST_$REMOVE_SEG((locate_request_t *)mste, va, seg, segno,
                            (((uint8_t)(mste->location >> 24) & MSTE_LOC_FIELD_MASK) >> 2 ==
                             MSTE_LOC_FIELD_ALL) ? (boolean)0xFF : 0);
        }

        /* 0x00E44A3A-0x00E44A52 */
        mste->unknown_0a &= MSTE_0A_KEEP_MASK;
        if ((mode & MST_UNMAP_KEEP_ENTRY) != 0) {
            mste->unknown_0a |= MSTE_0A_UNMAPPED;
        } else {
            mste->uid.high = 0;
        }

    next:
        /* 0x00E44A56-0x00E44A5E */
        va += 0x8000;
        seg++;
    }

    /* 0x00E44A94-0x00E44AA0 */
    ML_$UNLOCK(MST_UNMAP_LOCK);
    *status = result;
}
